/* From Uiverse.io by ArturCodeCraft - Tags: button, scroll to top, scroll */
/* <reset-style> ============================ */
.__UIV_SCOPE__ a {
  text-decoration: none;
}
/* <main-style> ============================ */
.__UIV_SCOPE__ .scroll-up {
	/* position: fixed; */
  right: 3rem;
  bottom: -50%;
  z-index: 10;
  width: 32px;
  height: 32px;
  border-radius: 4px;
  background-color: rgba(29, 29, 31, 0.7);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  transition: bottom .4s, transform .4s;
}

.__UIV_SCOPE__ .scroll-up:hover {
  transform: translateY(-.25rem);
}

/* Show scroll-up */
.__UIV_SCOPE__ ._show-scroll {
  bottom: 3rem;
}

@media (max-width: 1199.98px) {
  .__UIV_SCOPE__ .scroll-up {
    right: 1rem;
  }
}
